CREATE DEFINER=`rucma`@`%` PROCEDURE `actualizar_idCurso` ()   BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE v_idRegistro INT;
    DECLARE v_curso VARCHAR(255);
    DECLARE v_idCurso INT;

    
    DECLARE cur CURSOR FOR
        SELECT idRegistro, curso
        FROM tbl_registrocertificado;

    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO v_idRegistro, v_curso;
        IF done THEN
            LEAVE read_loop;
        END IF;

        
        SELECT idCurso INTO v_idCurso
        FROM tbl_cursos
        WHERE nombre = v_curso
        LIMIT 1;

        
        IF v_idCurso IS NOT NULL THEN
            UPDATE tbl_registrocertificado
            SET idCurso = v_idCurso
            WHERE idRegistro = v_idRegistro;
        END IF;
    END LOOP;

    CLOSE cur;
END$$

CREATE DEFINER=`rucma`@`%` PROCEDURE `generar_y_actualizar_codigo` ()   BEGIN
    DECLARE done BOOLEAN DEFAULT FALSE;
    DECLARE pSalt VARCHAR(6);
    DECLARE idRegistro INT;

    
    DECLARE cur CURSOR FOR SELECT idRegistro FROM tbl_registrocertificado;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO idRegistro;
        IF done THEN
            LEAVE read_loop;
        END IF;

        
        SET pSalt = generateRandomString(6);

        
        UPDATE tbl_registrocertificado SET code = pSalt WHERE idRegistro = idRegistro;
    END LOOP;

    CLOSE cur;
END$$

CREATE DEFINER=`rucma`@`%` PROCEDURE `sp_certificado` (IN `pId` VARCHAR(100))   BEGIN

IF (pId=null) THEN
SET pId = null;
END IF;

SELECT 
  A.idRegistro
, A.nombre
, A.apellido
, A.nacionalidad
, A.fechaNac
, A.lugarNac
, A.dni 
, C.nombre pais
, A.sexo
, B.nombre AS curso_es
, B.nombreingles AS curso_en
, B.reglas AS reglas_es
, B.reglasin AS reglas_en
, A.lugarEntre
, A.fechaInicio
, A.fechaFinal
, D.descripcion AS modalidad
, A.duracion
, A.codigo
, A.fechaEmision
, A.fechaExpiracion
, E.idCategoria
, E.descripcion AS categoria
, A.estado
FROM tbl_registrocertificado A
INNER JOIN tbl_cursos B ON (B.idCurso = A.idCurso)
INNER JOIN tbl_pais C ON (C.idPais = A.idPais)
INNER JOIN tbl_modalidad D ON (D.idModalidad = A.idModalidad)
INNER JOIN tbl_categoria E ON (E.idCategoria = A.idCategoria)
WHERE A.codigo = pId;

END$$

