CREATE DEFINER=`rucma`@`%` PROCEDURE `sp_CountReporte` (IN `pFechaEmision` VARCHAR(50), IN `pFechaExpiracion` VARCHAR(50), IN `pIdPais` INT, IN `pBusqueda` VARCHAR(100), IN `pPaginador` INT, IN `pPag` INT)   BEGIN
   DECLARE vSQL LONGTEXT;
   DECLARE vCond LONGTEXT;

SET vSQL = 'SELECT count(A.nombre) as cantidad
				FROM tbl_registrocertificado A
				INNER JOIN tbl_cursos B ON (B.idCurso = A.idCurso)
				INNER JOIN tbl_pais C ON (C.idPais = A.idPais)
				WHERE 0=0';

   IF pFechaEmision IS NOT NULL and pFechaEmision <>'' THEN
	   SET vSQL=Concat(vSQL ,' AND A.fechaEmision >= ' , QUOTE(pFechaEmision));
	END IF;

	IF pFechaExpiracion IS NOT NULL and pFechaExpiracion <>'' THEN
	   SET vSQL=Concat(vSQL ,' AND A.fechaExpiracion <= ' , QUOTE(pFechaExpiracion));
	END IF;
	IF pIdPais <> 0 THEN
	   SET vSQL=Concat(vSQL ,' AND A.idPais= ' , pIdPais );
	END IF;

	IF pBusqueda IS NOT NULL and pBusqueda <>'' THEN
		SET vSQL=Concat(vSQL ,' AND ( A.nombre LIKE ' , QUOTE(CONCAT('%', pBusqueda, '%')));
		SET vSQL=Concat(vSQL ,' OR A.apellido LIKE ' , QUOTE(CONCAT('%', pBusqueda, '%')));
		SET vSQL=Concat(vSQL ,' OR B.nombre LIKE ' , QUOTE(CONCAT('%', pBusqueda, '%')));
   	SET vSQL=Concat(vSQL ,' OR A.codigo LIKE ' , QUOTE(CONCAT('%', pBusqueda, '%')));
   	SET vSQL=Concat(vSQL ,' OR C.nombre LIKE ' , QUOTE(CONCAT('%', pBusqueda, '%')), ')');
	END IF;

	  SET vSQL = Concat(vSQL , ' ORDER BY ', 'A.idRegistro');

   IF (pPag = 0) THEN
      SET vSQL=Concat(vSQL ,' LIMIT ', pPaginador, ' ,', 5);
   ELSE
      SET vSQL=Concat(vSQL ,' LIMIT ', pPaginador, ' ,', pPag);
   END IF;


	set @stmt_str = vSQL;
	prepare stmt from @stmt_str;
	execute stmt;
	deallocate prepare stmt;

END$$

