CREATE DEFINER=`rucma`@`%` PROCEDURE `sp_InsertForm` (IN `pNombre` VARCHAR(50), IN `pApellido` VARCHAR(50), IN `pNacionalidad` VARCHAR(100), IN `pFechaNac` DATE, IN `pLugarNac` VARCHAR(100), IN `pDni` VARCHAR(50), IN `pIdPais` INT, IN `pSexo` CHAR(1), IN `pIdCurso` INT, IN `pIdModalidad` INT, IN `pLugarEntre` VARCHAR(100), IN `pDuracion` INT, IN `pFechaInicio` DATE, IN `pFechaFinal` DATE, IN `pFechaEmision` DATE, IN `pFechaExpiracion` DATE, IN `pCodigo` VARCHAR(50), IN `pCategoria` INT)   BEGIN
DECLARE conse INT;
DECLARE ID INT;
DECLARE pSalt VARCHAR(32);
DECLARE pHash VARCHAR(255);


SET pSalt= (SELECT generateRandomString(6));
SET pHash = (SELECT SHA2(CONCAT(pCodigo, pSalt), 512));


VALUES (UPPER(pNombre), UPPER(pApellido), pNacionalidad,pFechaNac, pLugarNac, pDni, pIdPais, pSexo, pIdCurso, pIdModalidad, pLugarEntre, pDuracion, pFechaInicio, pFechaFinal, pFechaEmision, pFechaExpiracion, pCodigo, pCategoria, pSalt, pHash);

SET conse = (SELECT consecutivo FROM tbl_consecutivo WHERE idConsecutivo = pIdPais);

UPDATE tbl_consecutivo SET consecutivo = conse + 1
WHERE idConsecutivo = pIdPais;





SELECT pCodigo AS respuesta;

END$$

