CREATE DEFINER=`rucma`@`%` PROCEDURE `sp_validaIdCertificado` (IN `pCodigo` VARCHAR(50), OUT `pError` VARCHAR(255))  NO SQL BEGIN
    DECLARE pSalt VARCHAR(32);
    DECLARE pHash VARCHAR(255);

    
    SET pError = '';

    
    BEGIN
        DECLARE errorText VARCHAR(255);

        DECLARE EXIT HANDLER FOR SQLSTATE '45000'
        BEGIN
            GET DIAGNOSTICS CONDITION 1 errorText = MESSAGE_TEXT;
            SET pError = errorText;
        END;

        
        IF LENGTH(pCodigo) = 0 THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El código no puede estar vacío';
        END IF;
 
        
        SELECT code INTO pSalt FROM tbl_registrocertificado WHERE codigo = pCodigo AND estado = 'E' LIMIT 1;
        IF pSalt IS NULL THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El código ingresado no es válido';
        END IF;

        
        SET pHash = SHA2(CONCAT(pCodigo, pSalt), 512);

        
        IF NOT EXISTS(SELECT 1 FROM tbl_registrocertificado WHERE hashcode = pHash) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El certificado correspondiente al código ingresado no existe o ha sido revocado';
        END IF;

        
        SELECT nombre, apellido, dni, codigo, fechaEmision, fechaExpiracion, idPais FROM tbl_registrocertificado
        WHERE hashcode = pHash;

    END;

    
    IF LENGTH(pError) > 0 THEN
        SELECT NULL AS nombre, NULL AS apellido, NULL AS dni, NULL AS fechaEmision, NULL AS fechaExpiracion;
    END IF;

END$$

CREATE DEFINER=`rucma`@`%` PROCEDURE `sp_verifyCode` (IN `pCode` VARCHAR(255))   BEGIN

SELECT codigo FROM tbl_code A
INNER JOIN tbl_registrocertificado B ON (B.idRegistro = A.id)
WHERE tokens IN(pCode);

END$$

CREATE DEFINER=`rucma`@`%` PROCEDURE `updateCodesAndHashcodes` ()   BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE randomCode VARCHAR(6);
    DECLARE pHash VARCHAR(128);
    DECLARE currentId INT;
    DECLARE currentCodigo VARCHAR(255);

    
    DECLARE cur CURSOR FOR SELECT idRegistro, codigo FROM tbl_registrocertificado;

    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    
    OPEN cur;

    
    read_loop: LOOP
        FETCH cur INTO currentId, currentCodigo;
        IF done THEN
            LEAVE read_loop;
        END IF;

        
        SET randomCode = generateRandomString(6);

        
        SET pHash = SHA2(CONCAT(currentCodigo, randomCode), 512);

        
        UPDATE tbl_registrocertificado
        SET code = randomCode, hashcode = pHash
        WHERE idRegistro = currentId;
    END LOOP;

    
    CLOSE cur;
END$$

CREATE DEFINER=`rucma`@`%` PROCEDURE `UpdateFechaExpiracionYFinal` ()   BEGIN
    
    UPDATE tbl_registrocertificado
    SET fechaExpiracion = DATE_ADD(fechaEmision, INTERVAL 5 YEAR),
        fechaFinal = fechaEmision
    WHERE fechaExpiracion is NULL AND fechaEmision is not NULL AND curso is not NULL;

END$$

