CREATE DEFINER=`rucma`@`%` FUNCTION `generateRandomString` (`length` INT) RETURNS VARCHAR(255) CHARSET utf8mb4 COLLATE utf8mb4_general_ci DETERMINISTIC BEGIN

DECLARE characters VARCHAR(255);
    DECLARE charactersLength INT;
    DECLARE randomString VARCHAR(255);
    DECLARE i INT DEFAULT 0;
    
    SET characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    SET charactersLength = LENGTH(characters);
    SET randomString = '';
    
    WHILE i < length DO
        SET randomString = CONCAT(randomString, SUBSTR(characters, FLOOR(RAND() * charactersLength) + 1, 1));
        SET i = i + 1;
    END WHILE;
    
    RETURN randomString;

END$$

